function parseCustomDate(dateStr) {
  if (!dateStr) return null;

  const parts = dateStr.match(
    /(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})\s+(AM|PM)/i
  );

  if (!parts) return new Date(dateStr);

  const day = parseInt(parts[1], 10);
  const month = parseInt(parts[2], 10) - 1;
  const year = parseInt(parts[3], 10);
  let hour = parseInt(parts[4], 10);
  const minute = parseInt(parts[5], 10);
  const ampm = parts[6].toUpperCase();

  if (ampm === 'PM' && hour < 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;

  return new Date(year, month, day, hour, minute);
}

function formatDDMMYYYY(d) {
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
}

return $input.all().map(item => {
  const startStr = item.json.body?.start_datetime_est;
  const endStr = item.json.body?.end_datetime_est;

  if (!startStr || !endStr) {
    return {
      json: {
        ...item.json,
        error: 'Missing start_datetime_est or end_datetime_est'
      }
    };
  }

  const startBase = parseCustomDate(startStr);
  const endBase = parseCustomDate(endStr);

  // META
  const metaStart = new Date(startBase);
  metaStart.setHours(metaStart.getHours() - 3);

  const metaEnd = new Date(endBase);
  metaEnd.setHours(metaEnd.getHours() - 3);
  metaEnd.setSeconds(metaEnd.getSeconds() - 1);

  // GOOGLE
  // googleStart = actualStart + 1 day
  // googleEnd   = actualEnd
  const googleStart = new Date(startBase);
  googleStart.setDate(googleStart.getDate() + 1);

  const googleEnd = new Date(endBase);

  return {
    json: {
      ...item.json,
      meta_start: formatDDMMYYYY(metaStart),
      meta_end: formatDDMMYYYY(metaEnd),
      google_start: formatDDMMYYYY(googleStart),
      google_end: formatDDMMYYYY(googleEnd),
      Meta: `${formatDDMMYYYY(metaStart)} - ${formatDDMMYYYY(metaEnd)}`,
      Google: `${formatDDMMYYYY(googleStart)} - ${formatDDMMYYYY(googleEnd)}`
    }
  };
});
